begin;
do $guard$ declare batch_content jsonb := $senior_content$[{"source_id":4131,"word":"climatology","meaning":"氣候學","example":"The climatology lesson compared weather patterns over many decades.","example_zh":"氣候學課比較數十年間的天氣型態。","original_meaning":"氣候學","original_example":"Study climatology.","original_example_zh":"研讀氣候學。"},{"source_id":4132,"word":"coagulate","meaning":"凝結；凝固","example":"The egg white began to coagulate as it heated.","example_zh":"蛋白受熱時開始凝固。","original_meaning":"凝結","original_example":"Blood coagulates.","original_example_zh":"血液凝固。"},{"source_id":4133,"word":"coercion","meaning":"脅迫","example":"The witness said she had signed the agreement under coercion.","example_zh":"證人說她是在脅迫下簽署協議。","original_meaning":"脅迫","original_example":"Under coercion.","original_example_zh":"在脅迫之下。"},{"source_id":4134,"word":"cognition","meaning":"認知","example":"The lesson explored cognition through puzzles about memory and attention.","example_zh":"課程透過記憶與注意力謎題探討認知。","original_meaning":"認知","original_example":"Human cognition.","original_example_zh":"人類認知。"},{"source_id":4135,"word":"collaboration","meaning":"合作","example":"Their collaboration produced a stronger bridge model.","example_zh":"他們合作製作出更堅固的模型橋。","original_meaning":"合作","original_example":"International collaboration.","original_example_zh":"國際合作。"},{"source_id":4136,"word":"collective","meaning":"集體的","example":"The garden's success was the result of a collective effort.","example_zh":"花園的成功來自集體努力。","original_meaning":"集體的","original_example":"Collective bargaining.","original_example_zh":"集體協商。"},{"source_id":4137,"word":"colonialism","meaning":"殖民主義","example":"The history exhibit examined the lasting effects of colonialism.","example_zh":"歷史展覽探討殖民主義的長遠影響。","original_meaning":"殖民主義","original_example":"The age of colonialism.","original_example_zh":"殖民主義時代。"},{"source_id":4138,"word":"colonization","meaning":"殖民化","example":"The lesson traced the colonization of the island by an overseas power.","example_zh":"課程追溯海外強權殖民那座島嶼的過程。","original_meaning":"殖民化","original_example":"European colonization.","original_example_zh":"歐洲殖民。"},{"source_id":4139,"word":"combustion","meaning":"燃燒","example":"The exhibit showed how combustion releases energy from fuel.","example_zh":"展覽展示燃料燃燒如何釋放能量。","original_meaning":"燃燒","original_example":"Internal combustion engine.","original_example_zh":"內燃機。"},{"source_id":4140,"word":"commemoration","meaning":"紀念","example":"The school held a commemoration for the town's founders.","example_zh":"學校舉行紀念城鎮創建者的活動。","original_meaning":"紀念","original_example":"A war commemoration.","original_example_zh":"一場戰爭紀念活動。"},{"source_id":4141,"word":"commissioner","meaning":"委員","example":"The commissioner inspected the new community sports center.","example_zh":"委員視察新社區運動中心。","original_meaning":"委員","original_example":"A police commissioner.","original_example_zh":"警察局長。"},{"source_id":4142,"word":"communique","meaning":"公報","example":"The representatives issued a communique after the meeting.","example_zh":"代表在會議後發布公報。","original_meaning":"公報","original_example":"An official communique.","original_example_zh":"官方公報。"},{"source_id":4143,"word":"compartment","meaning":"隔間","example":"She placed the small tools in a separate compartment of the box.","example_zh":"她把小工具放在盒子的獨立隔間。","original_meaning":"隔間","original_example":"A storage compartment.","original_example_zh":"儲物格。"},{"source_id":4144,"word":"compassionate","meaning":"有同情心的","example":"The compassionate volunteer listened patiently to the worried visitor.","example_zh":"富同情心的志工耐心聆聽擔心的訪客。","original_meaning":"有同情心的","original_example":"A compassionate person.","original_example_zh":"一位富有同情心的人。"},{"source_id":4145,"word":"competence","meaning":"能力","example":"His competence in first aid reassured the event organizers.","example_zh":"他在急救方面的能力讓活動主辦者安心。","original_meaning":"能力","original_example":"Professional competence.","original_example_zh":"專業能力。"},{"source_id":4146,"word":"complacency","meaning":"自滿","example":"The early success led to complacency, and the team stopped checking its work.","example_zh":"初期成功讓團隊自滿，不再仔細檢查作品。","original_meaning":"自滿","original_example":"Avoid complacency.","original_example_zh":"避免自滿。"},{"source_id":4147,"word":"complexion","meaning":"膚色","example":"The portrait captured her warm complexion in the afternoon light.","example_zh":"肖像捕捉她在午後光線下溫暖的膚色。","original_meaning":"膚色","original_example":"A fair complexion.","original_example_zh":"白皙的膚色。"},{"source_id":4148,"word":"composition","meaning":"作曲；樂曲","example":"Her new composition featured a gentle melody for violin.","example_zh":"她的新作品以柔和的小提琴旋律為特色。","original_meaning":"作曲","original_example":"A musical composition.","original_example_zh":"一首樂曲。"},{"source_id":4149,"word":"comprehension","meaning":"理解","example":"Building the model improved our comprehension of the river system.","example_zh":"製作模型提升我們對河川系統的理解。","original_meaning":"理解","original_example":"Reading comprehension.","original_example_zh":"閱讀理解。"},{"source_id":4150,"word":"compressor","meaning":"壓縮機","example":"The technician inspected the compressor in the workshop.","example_zh":"技術人員在工坊檢查壓縮機。","original_meaning":"壓縮機","original_example":"An air compressor.","original_example_zh":"一台空氣壓縮機。"},{"source_id":4151,"word":"concealment","meaning":"隱藏","example":"The insect's concealment among the leaves made it difficult to spot.","example_zh":"昆蟲藏在葉間，讓人難以發現。","original_meaning":"隱藏","original_example":"In concealment.","original_example_zh":"隱瞞之中。"},{"source_id":4152,"word":"conception","meaning":"概念；構想","example":"Her conception of the garden began with a simple sketch.","example_zh":"她對花園的構想起於一張簡單草圖。","original_meaning":"概念","original_example":"A new conception.","original_example_zh":"一個新概念。"},{"source_id":4153,"word":"conciliation","meaning":"調解","example":"The teacher used conciliation to help the clubs settle their disagreement.","example_zh":"老師透過調解，幫助社團解決爭執。","original_meaning":"調解","original_example":"Seek conciliation.","original_example_zh":"尋求和解。"},{"source_id":4154,"word":"confirmation","meaning":"確認","example":"The email provided confirmation of the museum visit.","example_zh":"電子郵件確認了博物館參訪安排。","original_meaning":"確認","original_example":"Receive confirmation.","original_example_zh":"收到確認通知。"},{"source_id":4155,"word":"confrontation","meaning":"對峙","example":"The captain prevented a confrontation by inviting both teams to talk.","example_zh":"隊長邀請兩隊交談，避免發生對峙。","original_meaning":"對峙","original_example":"A military confrontation.","original_example_zh":"軍事對峙。"},{"source_id":4156,"word":"connotation","meaning":"含意","example":"The word's warm connotation made it suitable for the welcome message.","example_zh":"那個詞帶有溫暖含意，很適合用在歡迎訊息。","original_meaning":"含意","original_example":"A negative connotation.","original_example_zh":"帶有負面含義。"},{"source_id":4157,"word":"consecration","meaning":"奉獻；祝聖","example":"The painting depicted the consecration of the new church.","example_zh":"畫作描繪新教堂的祝聖儀式。","original_meaning":"奉獻","original_example":"A ceremony of consecration.","original_example_zh":"祝聖儀式。"},{"source_id":4158,"word":"constellation","meaning":"星座","example":"The astronomer pointed out a constellation in the clear night sky.","example_zh":"天文學家指出晴朗夜空中的一個星座。","original_meaning":"星座","original_example":"Identify constellations.","original_example_zh":"辨識星座。"},{"source_id":4159,"word":"consultation","meaning":"諮詢","example":"The architect arranged a consultation with the library staff.","example_zh":"建築師安排與圖書館員諮詢討論。","original_meaning":"諮詢","original_example":"Medical consultation.","original_example_zh":"醫療諮詢。"},{"source_id":4160,"word":"contamination","meaning":"污染；汙染物混入","example":"The test detected contamination in the pond water.","example_zh":"檢測發現池水受到污染。","original_meaning":"污染；汙染物混入","original_example":"The café stopped serving tap water until tests ruled out contamination.","original_example_zh":"檢測確認自來水沒有污染前，咖啡店暫停供應自來水。"},{"source_id":4161,"word":"contention","meaning":"爭論","example":"The location of the new bridge became a point of contention.","example_zh":"新橋的位置成了爭論焦點。","original_meaning":"爭論","original_example":"A point of contention.","original_example_zh":"爭議點。"},{"source_id":4162,"word":"contingency","meaning":"應急；可能發生的意外情況","example":"The guide prepared for the contingency of a sudden storm.","example_zh":"嚮導為突發風暴的可能情況預作準備。","original_meaning":"應急","original_example":"A contingency plan.","original_example_zh":"應變計畫。"},{"source_id":4163,"word":"contributor","meaning":"貢獻者","example":"She was a regular contributor to the school science magazine.","example_zh":"她經常為學校科學雜誌撰稿。","original_meaning":"貢獻者","original_example":"A major contributor.","original_example_zh":"主要貢獻者。"},{"source_id":4164,"word":"convalescence","meaning":"康復期","example":"During his convalescence, he spent quiet afternoons reading by the window.","example_zh":"康復期間，他在窗邊安靜閱讀，度過午後。","original_meaning":"康復期","original_example":"During convalescence.","original_example_zh":"在康復期間。"},{"source_id":4165,"word":"coordination","meaning":"協調","example":"Careful coordination helped the volunteers set up the festival on time.","example_zh":"細心協調，讓志工準時完成節慶布置。","original_meaning":"協調","original_example":"Team coordination.","original_example_zh":"團隊協調。"},{"source_id":4166,"word":"correspondence","meaning":"通信","example":"Their correspondence continued through letters for many years.","example_zh":"他們以書信往來持續多年。","original_meaning":"通信","original_example":"Business correspondence.","original_example_zh":"商務信函。"},{"source_id":4167,"word":"corruption","meaning":"腐敗","example":"The report exposed corruption in the awarding of public contracts.","example_zh":"報告揭露公共合約發包中的貪腐。","original_meaning":"腐敗","original_example":"Fight corruption.","original_example_zh":"打擊貪腐。"},{"source_id":4168,"word":"credentials","meaning":"資歷","example":"The museum checked the researcher's credentials before opening the archive.","example_zh":"博物館開放檔案前，先查核研究者資歷。","original_meaning":"資歷","original_example":"Present credentials.","original_example_zh":"出示證件。"},{"source_id":4169,"word":"criminology","meaning":"犯罪學","example":"The criminology seminar examined patterns in anonymous crime statistics.","example_zh":"犯罪學研討課研究匿名犯罪統計中的型態。","original_meaning":"犯罪學","original_example":"Study criminology.","original_example_zh":"研讀犯罪學。"},{"source_id":4170,"word":"cybersecurity","meaning":"網路安全","example":"The cybersecurity workshop taught students to recognize suspicious login requests.","example_zh":"網路安全工作坊教學生辨識可疑登入要求。","original_meaning":"網路安全","original_example":"Cybersecurity threats.","original_example_zh":"網路安全威脅。"},{"source_id":4171,"word":"debacle","meaning":"慘敗","example":"The outdoor performance became a debacle when the wind destroyed the scenery.","example_zh":"強風毀掉布景，使戶外演出一敗塗地。","original_meaning":"慘敗","original_example":"A financial debacle.","original_example_zh":"一場財務災難。"},{"source_id":4172,"word":"decentralization","meaning":"分權","example":"The decentralization of library services brought books closer to residents.","example_zh":"圖書館服務分散到各區，讓居民更方便借書。","original_meaning":"分權","original_example":"Government decentralization.","original_example_zh":"政府權力下放。"},{"source_id":4173,"word":"decommission","meaning":"除役；停用","example":"The museum will decommission the old lift before replacing it.","example_zh":"博物館將停用舊電梯，再更換新設備。","original_meaning":"除役","original_example":"Decommission a plant.","original_example_zh":"關閉一座工廠。"},{"source_id":4174,"word":"decontamination","meaning":"淨化；除污","example":"The laboratory had a separate room for equipment decontamination.","example_zh":"實驗室設有獨立設備除污室。","original_meaning":"淨化","original_example":"Environmental decontamination.","original_example_zh":"環境除污。"},{"source_id":4175,"word":"defamation","meaning":"誹謗","example":"The journalist checked the claims carefully to avoid defamation.","example_zh":"記者仔細查證說法，避免誹謗。","original_meaning":"誹謗","original_example":"A case of defamation.","original_example_zh":"一宗誹謗案。"},{"source_id":4176,"word":"dehydration","meaning":"脫水","example":"The health lesson explained the signs of dehydration.","example_zh":"健康課解說脫水的徵象。","original_meaning":"脫水","original_example":"Prevent dehydration.","original_example_zh":"防止脫水。"},{"source_id":4177,"word":"delegation","meaning":"代表團","example":"The visiting delegation toured the school's science laboratories.","example_zh":"來訪代表團參觀學校科學實驗室。","original_meaning":"代表團","original_example":"A trade delegation.","original_example_zh":"一個貿易代表團。"},{"source_id":4178,"word":"delinquency","meaning":"犯罪","example":"The program aimed to reduce juvenile delinquency through mentoring.","example_zh":"這項計畫透過導師陪伴，致力減少青少年犯罪。","original_meaning":"犯罪","original_example":"Juvenile delinquency.","original_example_zh":"少年犯罪。"},{"source_id":4179,"word":"deluge","meaning":"洪水","example":"A deluge filled the normally dry channel with rushing water.","example_zh":"洪水使平常乾涸的水道湧入急流。","original_meaning":"洪水","original_example":"A deluge of rain.","original_example_zh":"傾盆大雨。"},{"source_id":4180,"word":"demarcation","meaning":"劃界","example":"The low stone wall formed a clear demarcation between the two gardens.","example_zh":"矮石牆清楚劃分兩座花園。","original_meaning":"劃界","original_example":"A line of demarcation.","original_example_zh":"分界線。"},{"source_id":4181,"word":"demolition","meaning":"拆除","example":"The demolition of the unsafe shed made room for a new workshop.","example_zh":"拆除不安全棚屋，騰出空間興建新工坊。","original_meaning":"拆除","original_example":"Building demolition.","original_example_zh":"建築拆除。"},{"source_id":4182,"word":"denunciation","meaning":"公開譴責","example":"The mayor's denunciation of illegal dumping drew public attention.","example_zh":"市長公開譴責非法傾倒垃圾，引起關注。","original_meaning":"公開譴責","original_example":"A public denunciation.","original_example_zh":"公開譴責。"},{"source_id":4183,"word":"derivative","meaning":"衍生物","example":"The chemist displayed a model of a derivative of the original compound.","example_zh":"化學家展示原化合物一種衍生物的模型。","original_meaning":"衍生物","original_example":"A chemical derivative.","original_example_zh":"一種化學衍生物。"},{"source_id":4184,"word":"despotism","meaning":"專制","example":"The history course examined despotism in the ancient empire.","example_zh":"歷史課探討古代帝國的專制統治。","original_meaning":"專制","original_example":"Oppose despotism.","original_example_zh":"反對專制。"},{"source_id":4185,"word":"destitution","meaning":"赤貧","example":"The charity helped families living in destitution obtain basic supplies.","example_zh":"慈善團體幫助生活赤貧的家庭取得基本物資。","original_meaning":"赤貧","original_example":"Live in destitution.","original_example_zh":"過著赤貧的生活。"},{"source_id":4186,"word":"deterioration","meaning":"惡化","example":"The bridge's deterioration became clear after years of rain.","example_zh":"經過多年雨淋，橋梁劣化已很明顯。","original_meaning":"惡化","original_example":"Health deterioration.","original_example_zh":"健康惡化。"},{"source_id":4187,"word":"devolution","meaning":"權力下放","example":"The lesson explored the devolution of some powers to local governments.","example_zh":"課程探討將部分權力下放地方政府。","original_meaning":"權力下放","original_example":"Political devolution.","original_example_zh":"政治權力下放。"},{"source_id":4188,"word":"dexterity","meaning":"靈巧","example":"Her dexterity helped her fit the tiny model pieces together.","example_zh":"她手巧靈活，把微小模型零件接合在一起。","original_meaning":"靈巧","original_example":"Manual dexterity.","original_example_zh":"手部靈巧度。"},{"source_id":4189,"word":"dichotomy","meaning":"二分法","example":"The essay questioned the simple dichotomy between tradition and progress.","example_zh":"文章質疑把傳統與進步簡單對立的二分法。","original_meaning":"二分法","original_example":"A false dichotomy.","original_example_zh":"虛假二分法。"},{"source_id":4190,"word":"dictator","meaning":"獨裁者","example":"The novel described a dictator who refused to share power.","example_zh":"小說描寫一位拒絕分享權力的獨裁者。","original_meaning":"獨裁者","original_example":"A military dictator.","original_example_zh":"軍事獨裁者。"},{"source_id":4191,"word":"dignitaries","meaning":"政要","example":"Local dignitaries attended the opening of the new museum.","example_zh":"地方政要出席新博物館開幕。","original_meaning":"政要","original_example":"Foreign dignitaries.","original_example_zh":"外國政要。"},{"source_id":4192,"word":"diligence","meaning":"勤勉","example":"Her diligence showed in the careful records of every experiment.","example_zh":"每次實驗仔細記錄，展現她的勤勉。","original_meaning":"勤勉","original_example":"Show diligence.","original_example_zh":"展現勤奮。"},{"source_id":4193,"word":"diminution","meaning":"減少","example":"The class measured a gradual diminution in the water level.","example_zh":"班上測量水位逐漸下降的情況。","original_meaning":"減少","original_example":"A diminution in value.","original_example_zh":"價值的減損。"},{"source_id":4194,"word":"dinosaur","meaning":"恐龍","example":"The museum displayed the skeleton of a large dinosaur.","example_zh":"博物館展示大型恐龍骨架。","original_meaning":"恐龍","original_example":"Dinosaurs are extinct.","original_example_zh":"恐龍已經滅絕。"},{"source_id":4195,"word":"dioxin","meaning":"戴奧辛","example":"The exhibit discussed dioxin as an environmental pollutant.","example_zh":"展覽討論作為環境污染物的戴奧辛。","original_meaning":"戴奧辛","original_example":"Dioxin contamination.","original_example_zh":"二噁英污染。"},{"source_id":4196,"word":"diplomat","meaning":"外交官","example":"The diplomat helped the two groups reach a peaceful agreement.","example_zh":"外交官協助雙方達成和平協議。","original_meaning":"外交官","original_example":"A skilled diplomat.","original_example_zh":"一位老練的外交官。"},{"source_id":4197,"word":"disambiguation","meaning":"消歧義","example":"The dictionary's disambiguation helped us distinguish the word's two meanings.","example_zh":"字典的消歧義說明幫助我們分辨那個詞的兩種意思。","original_meaning":"消歧義","original_example":"Word disambiguation.","original_example_zh":"詞義消歧。"},{"source_id":4198,"word":"disclosure","meaning":"揭露","example":"The disclosure of the test results led the team to redesign the model.","example_zh":"測試結果公開後，團隊重新設計模型。","original_meaning":"揭露","original_example":"Full disclosure.","original_example_zh":"全面公開。"},{"source_id":4199,"word":"discrepancy","meaning":"差異","example":"We found a discrepancy between the drawing and the finished model.","example_zh":"我們發現圖面與完成模型有一處差異。","original_meaning":"差異","original_example":"A statistical discrepancy.","original_example_zh":"統計上的差異。"},{"source_id":4200,"word":"dispensation","meaning":"豁免","example":"The committee granted a dispensation from the usual deadline.","example_zh":"委員會批准豁免一般期限的要求。","original_meaning":"豁免","original_example":"A special dispensation.","original_example_zh":"特別豁免。"},{"source_id":4201,"word":"dissertation","meaning":"論文","example":"He completed a dissertation on the history of public gardens.","example_zh":"他完成一篇研究公共花園歷史的學位論文。","original_meaning":"論文","original_example":"Write a dissertation.","original_example_zh":"撰寫論文。"},{"source_id":4202,"word":"distillation","meaning":"蒸餾","example":"The model showed distillation by collecting water after evaporation and condensation.","example_zh":"模型展示透過蒸發與凝結收集水的蒸餾過程。","original_meaning":"蒸餾","original_example":"Water distillation.","original_example_zh":"水蒸餾。"},{"source_id":4203,"word":"diversification","meaning":"多元化","example":"The farm's diversification included growing vegetables as well as fruit.","example_zh":"農場推動多元化，除了水果也種蔬菜。","original_meaning":"多元化","original_example":"Market diversification.","original_example_zh":"市場多元化。"},{"source_id":4204,"word":"documentation","meaning":"文件","example":"The team prepared clear documentation of the restoration work.","example_zh":"團隊為修復工作準備清楚文件紀錄。","original_meaning":"文件","original_example":"Project documentation.","original_example_zh":"專案文件。"},{"source_id":4205,"word":"domestication","meaning":"馴化","example":"The exhibit explored the domestication of wild plants into crops.","example_zh":"展覽探討野生植物被馴化為作物的過程。","original_meaning":"馴化","original_example":"Animal domestication.","original_example_zh":"動物馴養。"},{"source_id":4206,"word":"dominion","meaning":"統治權","example":"The map showed the extent of the kingdom's dominion.","example_zh":"地圖顯示王國統治權涵蓋的範圍。","original_meaning":"統治權","original_example":"Under dominion.","original_example_zh":"受管轄。"},{"source_id":4207,"word":"dormitory","meaning":"宿舍","example":"The dormitory had a shared study room on the ground floor.","example_zh":"宿舍一樓設有共用自習室。","original_meaning":"宿舍","original_example":"A college dormitory.","original_example_zh":"大學宿舍。"},{"source_id":4208,"word":"dramatization","meaning":"戲劇化","example":"The students performed a dramatization of the village's founding story.","example_zh":"學生以戲劇演出村莊創建故事。","original_meaning":"戲劇化","original_example":"A TV dramatization.","original_example_zh":"電視劇改編。"},{"source_id":4209,"word":"dynasty","meaning":"朝代","example":"The museum arranged the pottery by dynasty.","example_zh":"博物館依朝代排列陶器。","original_meaning":"朝代","original_example":"The Tang Dynasty.","original_example_zh":"唐朝。"},{"source_id":4210,"word":"ecclesiastical","meaning":"教會的","example":"The archive preserved ecclesiastical records from the old cathedral.","example_zh":"檔案館保存老大教堂的教會紀錄。","original_meaning":"教會的","original_example":"Ecclesiastical law.","original_example_zh":"教會法。"},{"source_id":4211,"word":"economize","meaning":"節約","example":"We can economize on materials by reusing the leftover wood.","example_zh":"我們可以重複利用剩餘木材，節省材料。","original_meaning":"節約","original_example":"Economize resources.","original_example_zh":"節約資源。"},{"source_id":4212,"word":"editorial","meaning":"社論","example":"The newspaper's editorial supported protecting the riverside park.","example_zh":"報紙社論支持保護河岸公園。","original_meaning":"社論","original_example":"A newspaper editorial.","original_example_zh":"報紙社論。"},{"source_id":4213,"word":"electorate","meaning":"選民","example":"The candidates answered questions from the electorate at the public meeting.","example_zh":"候選人在公開會議回答選民提問。","original_meaning":"選民","original_example":"The electorate voted.","original_example_zh":"選民們投了票。"},{"source_id":4214,"word":"elongation","meaning":"延長；伸長","example":"The experiment measured the elongation of a spring under a small weight.","example_zh":"實驗測量彈簧掛上小砝碼後的伸長量。","original_meaning":"延長","original_example":"Metal elongation.","original_example_zh":"金屬伸長率。"},{"source_id":4215,"word":"emigration","meaning":"移出","example":"The old photographs documented the family's emigration to another country.","example_zh":"老照片記錄那個家庭移居另一國的經過。","original_meaning":"移出","original_example":"Mass emigration.","original_example_zh":"大規模移民。"},{"source_id":4216,"word":"eminence","meaning":"卓越；聲望","example":"The scientist's eminence attracted students from many universities.","example_zh":"那位科學家的卓越聲望吸引多所大學的學生。","original_meaning":"卓越","original_example":"A man of eminence.","original_example_zh":"一位傑出的人物。"},{"source_id":4217,"word":"empowerment","meaning":"賦權；自主能力提升","example":"The workshop promoted empowerment by teaching practical repair skills.","example_zh":"工作坊透過教授實用修繕技能，幫助參與者培養自主能力。","original_meaning":"賦權","original_example":"Women empowerment.","original_example_zh":"女性賦權。"},{"source_id":4218,"word":"emulation","meaning":"仿效","example":"Her emulation of the master's brushwork helped her learn new techniques.","example_zh":"她仿效大師筆法，學會新技巧。","original_meaning":"仿效","original_example":"In emulation of.","original_example_zh":"效法……"},{"source_id":4219,"word":"encroachment","meaning":"侵犯","example":"The new buildings caused encroachment on the meadow.","example_zh":"新建築逐漸侵占草地。","original_meaning":"侵犯","original_example":"Land encroachment.","original_example_zh":"土地侵佔。"},{"source_id":4220,"word":"enumeration","meaning":"列舉","example":"The report included an enumeration of the tools needed for the project.","example_zh":"報告列出專案所需的各項工具。","original_meaning":"列舉","original_example":"A detailed enumeration.","original_example_zh":"詳盡的列舉。"},{"source_id":4221,"word":"environmentalist","meaning":"環保人士","example":"The environmentalist encouraged residents to protect the wetlands.","example_zh":"環保人士鼓勵居民保護濕地。","original_meaning":"環保人士","original_example":"A prominent environmentalist.","original_example_zh":"一位傑出的環保人士。"},{"source_id":4222,"word":"epidemiology","meaning":"流行病學","example":"The epidemiology seminar examined patterns of illness across communities.","example_zh":"流行病學研討會研究不同社區的疾病分布型態。","original_meaning":"流行病學","original_example":"Study epidemiology.","original_example_zh":"研究流行病學。"},{"source_id":4223,"word":"epistemology","meaning":"認識論","example":"The epistemology class asked how people know whether a claim is justified.","example_zh":"認識論課探問，人們如何知道一項主張是否有根據。","original_meaning":"認識論","original_example":"The field of epistemology.","original_example_zh":"認識論領域。"},{"source_id":4224,"word":"eradication","meaning":"根除","example":"The gardeners planned the eradication of the invasive weeds.","example_zh":"園丁規劃根除入侵雜草。","original_meaning":"根除","original_example":"Disease eradication.","original_example_zh":"根除疾病。"},{"source_id":4225,"word":"establishment","meaning":"建立","example":"The establishment of the public library changed the town's cultural life.","example_zh":"公共圖書館成立，改變了城鎮的文化生活。","original_meaning":"建立","original_example":"The political establishment.","original_example_zh":"政治建制。"},{"source_id":4226,"word":"exacerbation","meaning":"惡化","example":"The heavy rain caused an exacerbation of the damage to the old roof.","example_zh":"大雨讓老屋頂的損壞更加嚴重。","original_meaning":"惡化","original_example":"Symptom exacerbation.","original_example_zh":"症狀惡化。"},{"source_id":4227,"word":"exaggeration","meaning":"誇張","example":"His description of the tiny model as enormous was an obvious exaggeration.","example_zh":"他把小模型說成巨大，顯然是誇張。","original_meaning":"誇張","original_example":"That is an exaggeration.","original_example_zh":"那是誇大其詞。"},{"source_id":4228,"word":"exclamation","meaning":"驚嘆","example":"An exclamation of delight greeted the finished bridge model.","example_zh":"完成的模型橋引來驚喜讚嘆。","original_meaning":"驚嘆","original_example":"An exclamation of surprise.","original_example_zh":"驚訝的驚呼。"},{"source_id":4229,"word":"exemption","meaning":"豁免","example":"The school granted an exemption from the fee to students who needed support.","example_zh":"學校讓需要協助的學生豁免繳費。","original_meaning":"豁免","original_example":"A tax exemption.","original_example_zh":"免稅待遇。"},{"source_id":4230,"word":"exhaustion","meaning":"精疲力竭","example":"The volunteers rested after working to the point of exhaustion.","example_zh":"志工工作得精疲力竭後休息。","original_meaning":"精疲力竭","original_example":"Suffer from exhaustion.","original_example_zh":"因疲憊不堪而受苦。"}]$senior_content$::jsonb; begin
perform 1 from public.word_bank w join jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) on w.id=c.source_id and w.word=c.word where w.level='senior' for update of w;
if (select count(*) from public.word_bank w join jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) on w.id=c.source_id and w.word=c.word where w.level='senior' and ((w.meaning,w.example,w.example_zh) is not distinct from (c.original_meaning,c.original_example,c.original_example_zh) or (w.meaning,w.example,w.example_zh) is not distinct from (c.meaning,c.example,c.example_zh))) <> 100 then raise exception 'Senior source rows changed; refusing overwrite'; end if;
update public.word_bank w set meaning=c.meaning,example=c.example,example_zh=c.example_zh from jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) where w.id=c.source_id and w.level='senior' and w.word=c.word;
end $guard$;
insert into public.word_illustrations(id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version) select id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version from jsonb_to_recordset($senior_rows$[{"id":"senior-climatology-01-v1","level":"senior","word":"climatology","sort_order":1,"sense":"氣候學","alt_zh":"高中生與老師在教室比較無字多年氣候圖表、地球模型與氣象照片。","example":"The climatology lesson compared weather patterns over many decades.","example_zh":"氣候學課比較數十年間的天氣型態。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/climatology-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-coagulate-01-v1","level":"senior","word":"coagulate","sort_order":1,"sense":"凝結；凝固","alt_zh":"成年烹飪老師向高中生示範平底鍋裡透明蛋白逐漸變白凝固，保持安全距離。","example":"The egg white began to coagulate as it heated.","example_zh":"蛋白受熱時開始凝固。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/coagulate-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-coercion-01-v1","level":"senior","word":"coercion","sort_order":1,"sense":"脅迫","alt_zh":"成年女性證人在法庭向法官陳述，桌上有協議文件，無威脅或暴力畫面。","example":"The witness said she had signed the agreement under coercion.","example_zh":"證人說她是在脅迫下簽署協議。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/coercion-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-cognition-01-v1","level":"senior","word":"cognition","sort_order":1,"sense":"認知","alt_zh":"高中生在老師帶領下專注排列記憶圖卡與幾何拼圖，無文字。","example":"The lesson explored cognition through puzzles about memory and attention.","example_zh":"課程透過記憶與注意力謎題探討認知。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/cognition-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-collaboration-01-v1","level":"senior","word":"collaboration","sort_order":1,"sense":"合作","alt_zh":"高中團隊在工坊共同支撐、組裝精巧木模型橋，老師在旁。","example":"Their collaboration produced a stronger bridge model.","example_zh":"他們合作製作出更堅固的模型橋。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/collaboration-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-collective-01-v1","level":"senior","word":"collective","sort_order":1,"sense":"集體的","alt_zh":"不同背景的高中生與成年社區志工一起完成整齊茂盛的花園。","example":"The garden's success was the result of a collective effort.","example_zh":"花園的成功來自集體努力。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/collective-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-colonialism-01-v1","level":"senior","word":"colonialism","sort_order":1,"sense":"殖民主義","alt_zh":"高中生在博物館聽成年導覽員客觀介紹古老殖民貿易地圖與文化文物，無刻板醜化。","example":"The history exhibit examined the lasting effects of colonialism.","example_zh":"歷史展覽探討殖民主義的長遠影響。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/colonialism-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-colonization-01-v1","level":"senior","word":"colonization","sort_order":1,"sense":"殖民化","alt_zh":"老師以虛構歷史島嶼模型解說外來成年殖民官員建立據點，無戰鬥傷害。","example":"The lesson traced the colonization of the island by an overseas power.","example_zh":"課程追溯海外強權殖民那座島嶼的過程。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/colonization-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-combustion-01-v1","level":"senior","word":"combustion","sort_order":1,"sense":"燃燒","alt_zh":"高中生在科技館觀看封閉安全展示模型中的小型火焰與能量教具，無燃燒操作。","example":"The exhibit showed how combustion releases energy from fuel.","example_zh":"展覽展示燃料燃燒如何釋放能量。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/combustion-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-commemoration-01-v1","level":"senior","word":"commemoration","sort_order":1,"sense":"紀念","alt_zh":"高中生與成年居民在歷史紀念碑前莊重獻花，無可讀文字。","example":"The school held a commemoration for the town's founders.","example_zh":"學校舉行紀念城鎮創建者的活動。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/commemoration-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-commissioner-01-v1","level":"senior","word":"commissioner","sort_order":1,"sense":"委員","alt_zh":"成年公共委員與管理員在明亮社區運動館查看無障礙通道和安全設備。","example":"The commissioner inspected the new community sports center.","example_zh":"委員視察新社區運動中心。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/commissioner-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-communique-01-v1","level":"senior","word":"communique","sort_order":1,"sense":"公報","alt_zh":"成年國際代表在會議廳向記者展示正式聯合文件，無可讀文字或真實政黨。","example":"The representatives issued a communique after the meeting.","example_zh":"代表在會議後發布公報。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/communique-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-compartment-01-v1","level":"senior","word":"compartment","sort_order":1,"sense":"隔間","alt_zh":"高中女生在工坊把小型模型工具整齊放入分格工具盒。","example":"She placed the small tools in a separate compartment of the box.","example_zh":"她把小工具放在盒子的獨立隔間。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/compartment-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-compassionate-01-v1","level":"senior","word":"compassionate","sort_order":1,"sense":"有同情心的","alt_zh":"成年志工在社區中心溫柔陪伴神情憂慮的成年訪客。","example":"The compassionate volunteer listened patiently to the worried visitor.","example_zh":"富同情心的志工耐心聆聽擔心的訪客。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/compassionate-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-competence-01-v1","level":"senior","word":"competence","sort_order":1,"sense":"能力","alt_zh":"成年合格救護員在社區活動急救站向主辦人展示整備用品與訓練證明，無操作步驟。","example":"His competence in first aid reassured the event organizers.","example_zh":"他在急救方面的能力讓活動主辦者安心。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/competence-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-complacency-01-v1","level":"senior","word":"complacency","sort_order":1,"sense":"自滿","alt_zh":"高中模型團隊過早慶祝，桌上的橋有明顯未固定支架，老師溫和提醒。","example":"The early success led to complacency, and the team stopped checking its work.","example_zh":"初期成功讓團隊自滿，不再仔細檢查作品。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/complacency-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-complexion-01-v1","level":"senior","word":"complexion","sort_order":1,"sense":"膚色","alt_zh":"成年畫家在工作室描繪穿完整日常服裝的成年女性肖像，自然尊重呈現膚色，無美醜評比。","example":"The portrait captured her warm complexion in the afternoon light.","example_zh":"肖像捕捉她在午後光線下溫暖的膚色。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/complexion-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-composition-01-v1","level":"senior","word":"composition","sort_order":1,"sense":"作曲；樂曲","alt_zh":"高中作曲學生在音樂桌寫樂譜，同學用小提琴試奏，譜面不可辨識。","example":"Her new composition featured a gentle melody for violin.","example_zh":"她的新作品以柔和的小提琴旋律為特色。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/composition-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-comprehension-01-v1","level":"senior","word":"comprehension","sort_order":1,"sense":"理解","alt_zh":"高中生與老師在完成的立體河川模型前恍然理解支流匯流。","example":"Building the model improved our comprehension of the river system.","example_zh":"製作模型提升我們對河川系統的理解。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/comprehension-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-compressor-01-v1","level":"senior","word":"compressor","sort_order":1,"sense":"壓縮機","alt_zh":"成年技師穿完整安全工作衣，檢查已停止運作的工業壓縮機，學生在安全區旁觀。","example":"The technician inspected the compressor in the workshop.","example_zh":"技術人員在工坊檢查壓縮機。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/compressor-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-concealment-01-v1","level":"senior","word":"concealment","sort_order":1,"sense":"隱藏","alt_zh":"高中生與自然老師在保育區遠距仔細尋找綠葉間擬態昆蟲。","example":"The insect's concealment among the leaves made it difficult to spot.","example_zh":"昆蟲藏在葉間，讓人難以發現。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/concealment-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-conception-01-v1","level":"senior","word":"conception","sort_order":1,"sense":"概念；構想","alt_zh":"高中女生在課桌把花園初步草圖與小模型並排，向同學解說。","example":"Her conception of the garden began with a simple sketch.","example_zh":"她對花園的構想起於一張簡單草圖。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/conception-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-conciliation-01-v1","level":"senior","word":"conciliation","sort_order":1,"sense":"調解","alt_zh":"成年老師在圓桌平靜引導兩組高中社團成員互相聆聽。","example":"The teacher used conciliation to help the clubs settle their disagreement.","example_zh":"老師透過調解，幫助社團解決爭執。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/conciliation-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-confirmation-01-v1","level":"senior","word":"confirmation","sort_order":1,"sense":"確認","alt_zh":"成年老師與高中生在電腦前查看帶博物館圖示與核取記號的無字行程確認。","example":"The email provided confirmation of the museum visit.","example_zh":"電子郵件確認了博物館參訪安排。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/confirmation-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-confrontation-01-v1","level":"senior","word":"confrontation","sort_order":1,"sense":"對峙","alt_zh":"高中球隊隊長在球場旁以友善手勢請兩隊緊張球員圍圈對話，無暴力。","example":"The captain prevented a confrontation by inviting both teams to talk.","example_zh":"隊長邀請兩隊交談，避免發生對峙。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/confrontation-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-connotation-01-v1","level":"senior","word":"connotation","sort_order":1,"sense":"含意","alt_zh":"高中寫作課裡，老師與學生比較歡迎卡片的不同語氣草稿，文字不可辨識。","example":"The word's warm connotation made it suitable for the welcome message.","example_zh":"那個詞帶有溫暖含意，很適合用在歡迎訊息。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/connotation-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-consecration-01-v1","level":"senior","word":"consecration","sort_order":1,"sense":"奉獻；祝聖","alt_zh":"宗教藝術博物館中的歷史畫作呈現成年神職人員與居民莊重參加新教堂祝聖，尊重呈現。","example":"The painting depicted the consecration of the new church.","example_zh":"畫作描繪新教堂的祝聖儀式。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/consecration-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-constellation-01-v1","level":"senior","word":"constellation","sort_order":1,"sense":"星座","alt_zh":"成年天文學家在安全觀星臺向高中生指出夜空一組星星，旁邊有無字星圖。","example":"The astronomer pointed out a constellation in the clear night sky.","example_zh":"天文學家指出晴朗夜空中的一個星座。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/constellation-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-consultation-01-v1","level":"senior","word":"consultation","sort_order":1,"sense":"諮詢","alt_zh":"成年建築師與圖書館員圍桌討論圖書館模型與讀者需求。","example":"The architect arranged a consultation with the library staff.","example_zh":"建築師安排與圖書館員諮詢討論。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/consultation-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-contamination-01-v1","level":"senior","word":"contamination","sort_order":1,"sense":"污染；汙染物混入","alt_zh":"成年環境研究員在實驗室查看密封池水樣本與無字檢測圖表，高中生旁觀，無飲用。","example":"The test detected contamination in the pond water.","example_zh":"檢測發現池水受到污染。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/contamination-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-contention-01-v1","level":"senior","word":"contention","sort_order":1,"sense":"爭論","alt_zh":"兩組成年社區代表在地景模型上分別指向不同橋址，主持人耐心協調。","example":"The location of the new bridge became a point of contention.","example_zh":"新橋的位置成了爭論焦點。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/contention-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-contingency-01-v1","level":"senior","word":"contingency","sort_order":1,"sense":"應急；可能發生的意外情況","alt_zh":"成年嚮導在健行前向高中生展示雨具、備用地圖與安全避雨場所模型。","example":"The guide prepared for the contingency of a sudden storm.","example_zh":"嚮導為突發風暴的可能情況預作準備。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/contingency-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-contributor-01-v1","level":"senior","word":"contributor","sort_order":1,"sense":"貢獻者","alt_zh":"高中女生向成年編輯老師交付有科學插圖的稿件，桌上放著校刊，無可讀文字。","example":"She was a regular contributor to the school science magazine.","example_zh":"她經常為學校科學雜誌撰稿。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/contributor-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-convalescence-01-v1","level":"senior","word":"convalescence","sort_order":1,"sense":"康復期","alt_zh":"成年康復者穿完整舒適服裝在明亮窗邊扶手椅讀書，家人陪伴，無傷口。","example":"During his convalescence, he spent quiet afternoons reading by the window.","example_zh":"康復期間，他在窗邊安靜閱讀，度過午後。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/convalescence-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-coordination-01-v1","level":"senior","word":"coordination","sort_order":1,"sense":"協調","alt_zh":"成年負責人與高中志工分工搬桌、掛裝飾與整理物資，動作有序。","example":"Careful coordination helped the volunteers set up the festival on time.","example_zh":"細心協調，讓志工準時完成節慶布置。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/coordination-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-correspondence-01-v1","level":"senior","word":"correspondence","sort_order":1,"sense":"通信","alt_zh":"成年長者在家中整理多年信件與朋友照片，桌上有筆與信封，文字不可辨識。","example":"Their correspondence continued through letters for many years.","example_zh":"他們以書信往來持續多年。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/correspondence-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-corruption-01-v1","level":"senior","word":"corruption","sort_order":1,"sense":"腐敗","alt_zh":"成年調查記者與行政人員在辦公室仔細查看可疑合約與帳冊，無實際賄賂方法。","example":"The report exposed corruption in the awarding of public contracts.","example_zh":"報告揭露公共合約發包中的貪腐。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/corruption-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-credentials-01-v1","level":"senior","word":"credentials","sort_order":1,"sense":"資歷","alt_zh":"成年研究員向檔案館員出示無字識別證與正式學術文件。","example":"The museum checked the researcher's credentials before opening the archive.","example_zh":"博物館開放檔案前，先查核研究者資歷。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/credentials-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-criminology-01-v1","level":"senior","word":"criminology","sort_order":1,"sense":"犯罪學","alt_zh":"成年大學生與教授在教室分析無字統計圖與城市模型，無犯罪操作。","example":"The criminology seminar examined patterns in anonymous crime statistics.","example_zh":"犯罪學研討課研究匿名犯罪統計中的型態。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/criminology-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-cybersecurity-01-v1","level":"senior","word":"cybersecurity","sort_order":1,"sense":"網路安全","alt_zh":"成年老師向高中生展示無字電腦鎖頭與警示圖示，學生比較安全登入示意，無攻擊步驟。","example":"The cybersecurity workshop taught students to recognize suspicious login requests.","example_zh":"網路安全工作坊教學生辨識可疑登入要求。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/cybersecurity-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-debacle-01-v1","level":"senior","word":"debacle","sort_order":1,"sense":"慘敗","alt_zh":"風停後安全戶外舞臺的紙板布景倒落，高中劇團失望整理，無受傷或危急情況。","example":"The outdoor performance became a debacle when the wind destroyed the scenery.","example_zh":"強風毀掉布景，使戶外演出一敗塗地。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/debacle-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-decentralization-01-v1","level":"senior","word":"decentralization","sort_order":1,"sense":"分權","alt_zh":"高中生觀察城鎮模型中中央圖書館與多個社區小分館，居民就近使用。","example":"The decentralization of library services brought books closer to residents.","example_zh":"圖書館服務分散到各區，讓居民更方便借書。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/decentralization-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-decommission-01-v1","level":"senior","word":"decommission","sort_order":1,"sense":"除役；停用","alt_zh":"成年技師在已封閉的舊電梯入口檢查停用文件，訪客走向安全樓梯，無維修細節。","example":"The museum will decommission the old lift before replacing it.","example_zh":"博物館將停用舊電梯，再更換新設備。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/decommission-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-decontamination-01-v1","level":"senior","word":"decontamination","sort_order":1,"sense":"淨化；除污","alt_zh":"成年實驗室人員穿適當防護衣，將密封器材箱放在專業除污室入口，無化學處理步驟。","example":"The laboratory had a separate room for equipment decontamination.","example_zh":"實驗室設有獨立設備除污室。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/decontamination-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-defamation-01-v1","level":"senior","word":"defamation","sort_order":1,"sense":"誹謗","alt_zh":"成年記者在新聞室核對訪談紀錄與資料，文字不可辨識，無真實指控。","example":"The journalist checked the claims carefully to avoid defamation.","example_zh":"記者仔細查證說法，避免誹謗。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/defamation-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-dehydration-01-v1","level":"senior","word":"dehydration","sort_order":1,"sense":"脫水","alt_zh":"成年健康教師在高中教室以無字人體與水分圖示說明脫水概念，無診斷或處置步驟。","example":"The health lesson explained the signs of dehydration.","example_zh":"健康課解說脫水的徵象。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/dehydration-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-delegation-01-v1","level":"senior","word":"delegation","sort_order":1,"sense":"代表團","alt_zh":"幾位成年國際代表與老師參觀高中實驗室，學生展示安全科學模型。","example":"The visiting delegation toured the school's science laboratories.","example_zh":"來訪代表團參觀學校科學實驗室。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/delegation-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-delinquency-01-v1","level":"senior","word":"delinquency","sort_order":1,"sense":"犯罪","alt_zh":"成年導師在社區工作坊耐心陪高中生修理腳踏車、討論學習目標，無標籤化或束縛。","example":"The program aimed to reduce juvenile delinquency through mentoring.","example_zh":"這項計畫透過導師陪伴，致力減少青少年犯罪。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/delinquency-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-deluge-01-v1","level":"senior","word":"deluge","sort_order":1,"sense":"洪水","alt_zh":"雨後水道湧流，成年環境老師與高中生從遠處穩固有護欄觀景臺觀看，無危險。","example":"A deluge filled the normally dry channel with rushing water.","example_zh":"洪水使平常乾涸的水道湧入急流。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/deluge-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-demarcation-01-v1","level":"senior","word":"demarcation","sort_order":1,"sense":"劃界","alt_zh":"高中生觀察一座低石牆，兩側花園邊界清楚，成年園丁在旁解說。","example":"The low stone wall formed a clear demarcation between the two gardens.","example_zh":"矮石牆清楚劃分兩座花園。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/demarcation-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-demolition-01-v1","level":"senior","word":"demolition","sort_order":1,"sense":"拆除","alt_zh":"成年專業工人在封閉安全區有序拆卸空舊棚屋，高中生在遠處旁觀。","example":"The demolition of the unsafe shed made room for a new workshop.","example_zh":"拆除不安全棚屋，騰出空間興建新工坊。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/demolition-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-denunciation-01-v1","level":"senior","word":"denunciation","sort_order":1,"sense":"公開譴責","alt_zh":"虛構成年市長在安全河岸向居民嚴肅指出垃圾問題，高中志工在旁，無文字。","example":"The mayor's denunciation of illegal dumping drew public attention.","example_zh":"市長公開譴責非法傾倒垃圾，引起關注。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/denunciation-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-derivative-01-v1","level":"senior","word":"derivative","sort_order":1,"sense":"衍生物","alt_zh":"成年化學老師向高中生比較兩個相近但有一處不同的球棍分子教具，無配方或反應操作。","example":"The chemist displayed a model of a derivative of the original compound.","example_zh":"化學家展示原化合物一種衍生物的模型。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/derivative-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-despotism-01-v1","level":"senior","word":"despotism","sort_order":1,"sense":"專制","alt_zh":"老師向高中生展示虛構成年帝王獨自控制議事的宮廷模型，無傷害或宣傳。","example":"The history course examined despotism in the ancient empire.","example_zh":"歷史課探討古代帝國的專制統治。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/despotism-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-destitution-01-v1","level":"senior","word":"destitution","sort_order":1,"sense":"赤貧","alt_zh":"成年志工在社區中心有尊嚴地把食物、毛毯與用品交給需要幫助的家庭。","example":"The charity helped families living in destitution obtain basic supplies.","example_zh":"慈善團體幫助生活赤貧的家庭取得基本物資。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/destitution-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-deterioration-01-v1","level":"senior","word":"deterioration","sort_order":1,"sense":"惡化","alt_zh":"成年工程師在封閉橋梁的安全入口查看腐朽木板，高中訪客遠距觀察。","example":"The bridge's deterioration became clear after years of rain.","example_zh":"經過多年雨淋，橋梁劣化已很明顯。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/deterioration-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-devolution-01-v1","level":"senior","word":"devolution","sort_order":1,"sense":"權力下放","alt_zh":"老師用中央與地方市政模型向高中生展示決策文件移交地方代表，無文字。","example":"The lesson explored the devolution of some powers to local governments.","example_zh":"課程探討將部分權力下放地方政府。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/devolution-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-dexterity-01-v1","level":"senior","word":"dexterity","sort_order":1,"sense":"靈巧","alt_zh":"高中女生在明亮工坊細心用安全鑷子組裝小木模型，同學讚賞。","example":"Her dexterity helped her fit the tiny model pieces together.","example_zh":"她手巧靈活，把微小模型零件接合在一起。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/dexterity-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-dichotomy-01-v1","level":"senior","word":"dichotomy","sort_order":1,"sense":"二分法","alt_zh":"高中寫作小組討論把古老建築與現代設計融合的模型，桌上原先兩組圖卡重新連接。","example":"The essay questioned the simple dichotomy between tradition and progress.","example_zh":"文章質疑把傳統與進步簡單對立的二分法。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/dichotomy-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-dictator-01-v1","level":"senior","word":"dictator","sort_order":1,"sense":"獨裁者","alt_zh":"高中生閱讀虛構政治小說，插畫呈現成年統治者獨坐高位、其他官員等待發言，無武器。","example":"The novel described a dictator who refused to share power.","example_zh":"小說描寫一位拒絕分享權力的獨裁者。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/dictator-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-dignitaries-01-v1","level":"senior","word":"dignitaries","sort_order":1,"sense":"政要","alt_zh":"幾位成年市政代表與博物館員在入口莊重參與開幕，高中生在旁歡迎，無真實政治人物。","example":"Local dignitaries attended the opening of the new museum.","example_zh":"地方政要出席新博物館開幕。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/dignitaries-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-diligence-01-v1","level":"senior","word":"diligence","sort_order":1,"sense":"勤勉","alt_zh":"高中女生在科學桌認真整理各次量測筆記與模型，老師欣慰觀察。","example":"Her diligence showed in the careful records of every experiment.","example_zh":"每次實驗仔細記錄，展現她的勤勉。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/diligence-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-diminution-01-v1","level":"senior","word":"diminution","sort_order":1,"sense":"減少","alt_zh":"高中生與老師觀察透明水槽與水位刻度的教學模型，無可讀數字。","example":"The class measured a gradual diminution in the water level.","example_zh":"班上測量水位逐漸下降的情況。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/diminution-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-dinosaur-01-v1","level":"senior","word":"dinosaur","sort_order":1,"sense":"恐龍","alt_zh":"高中參訪團在自然博物館抬頭欣賞完整巨大恐龍化石骨架。","example":"The museum displayed the skeleton of a large dinosaur.","example_zh":"博物館展示大型恐龍骨架。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/dinosaur-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-dioxin-01-v1","level":"senior","word":"dioxin","sort_order":1,"sense":"戴奧辛","alt_zh":"高中生在環境科學館聽成年研究員介紹密封污染物分子模型與環境圖示，無製備或暴露畫面。","example":"The exhibit discussed dioxin as an environmental pollutant.","example_zh":"展覽討論作為環境污染物的戴奧辛。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/dioxin-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-diplomat-01-v1","level":"senior","word":"diplomat","sort_order":1,"sense":"外交官","alt_zh":"成年外交官在中立會議桌協調兩組成年代表友善握手，無真實旗幟。","example":"The diplomat helped the two groups reach a peaceful agreement.","example_zh":"外交官協助雙方達成和平協議。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/diplomat-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-disambiguation-01-v1","level":"senior","word":"disambiguation","sort_order":1,"sense":"消歧義","alt_zh":"高中生在英語課比較同一詞的兩個不同情境圖卡與字典，文字不可辨識。","example":"The dictionary's disambiguation helped us distinguish the word's two meanings.","example_zh":"字典的消歧義說明幫助我們分辨那個詞的兩種意思。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/disambiguation-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-disclosure-01-v1","level":"senior","word":"disclosure","sort_order":1,"sense":"揭露","alt_zh":"高中團隊在老師面前展開測試紀錄，指著模型橋討論改良，無可讀文字。","example":"The disclosure of the test results led the team to redesign the model.","example_zh":"測試結果公開後，團隊重新設計模型。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/disclosure-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-discrepancy-01-v1","level":"senior","word":"discrepancy","sort_order":1,"sense":"差異","alt_zh":"高中生用尺比較模型屋窗戶與圖紙尺寸，老師指出不一致的位置。","example":"We found a discrepancy between the drawing and the finished model.","example_zh":"我們發現圖面與完成模型有一處差異。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/discrepancy-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-dispensation-01-v1","level":"senior","word":"dispensation","sort_order":1,"sense":"豁免","alt_zh":"成年委員在學校辦公室向高中參賽者交付延期許可文件，神情友善，無文字。","example":"The committee granted a dispensation from the usual deadline.","example_zh":"委員會批准豁免一般期限的要求。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/dispensation-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-dissertation-01-v1","level":"senior","word":"dissertation","sort_order":1,"sense":"論文","alt_zh":"成年研究生在大學圖書館整理厚論文、歷史花園照片與筆記，文字不可辨識。","example":"He completed a dissertation on the history of public gardens.","example_zh":"他完成一篇研究公共花園歷史的學位論文。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/dissertation-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-distillation-01-v1","level":"senior","word":"distillation","sort_order":1,"sense":"蒸餾","alt_zh":"成年科學老師在安全教室展示封閉水蒸餾教具，蒸氣經冷凝管成水滴，高中生遠距觀察，無酒精。","example":"The model showed distillation by collecting water after evaporation and condensation.","example_zh":"模型展示透過蒸發與凝結收集水的蒸餾過程。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/distillation-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-diversification-01-v1","level":"senior","word":"diversification","sort_order":1,"sense":"多元化","alt_zh":"成年農人帶高中生參觀果樹與多種蔬菜田並存的整齊農場。","example":"The farm's diversification included growing vegetables as well as fruit.","example_zh":"農場推動多元化，除了水果也種蔬菜。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/diversification-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-documentation-01-v1","level":"senior","word":"documentation","sort_order":1,"sense":"文件","alt_zh":"高中志工與成年修復師把歷史建築照片、圖紙與紀錄整齊裝訂，無可讀文字。","example":"The team prepared clear documentation of the restoration work.","example_zh":"團隊為修復工作準備清楚文件紀錄。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/documentation-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-domestication-01-v1","level":"senior","word":"domestication","sort_order":1,"sense":"馴化","alt_zh":"高中生在農業博物館觀察野生穀草到栽培穀物的教具與古代耕作模型。","example":"The exhibit explored the domestication of wild plants into crops.","example_zh":"展覽探討野生植物被馴化為作物的過程。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/domestication-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-dominion-01-v1","level":"senior","word":"dominion","sort_order":1,"sense":"統治權","alt_zh":"高中生在歷史教室觀察虛構古王國地圖模型，以同色範圍標示統治區域，無文字。","example":"The map showed the extent of the kingdom's dominion.","example_zh":"地圖顯示王國統治權涵蓋的範圍。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/dominion-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-dormitory-01-v1","level":"senior","word":"dormitory","sort_order":1,"sense":"宿舍","alt_zh":"成年大學生在整潔宿舍一樓共用書桌閱讀，窗外可見校園。","example":"The dormitory had a shared study room on the ground floor.","exampl